package store

import (
	"reflect"
	"testing"

	"github.com/mellifera/mellifera/internal/access"
)

// TestVisibleWhereShapes pins the four scope shapes of the visibility
// fragment (l6-accounts D3): see-all → no clause; scoped user → bound
// IN-list over the visible set; empty set and the zero Viewer → 1=0
// (fail closed). Args must be bound int64 values, never stringified.
func TestVisibleWhereShapes(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		viewer access.Viewer
		col    string
		clause string
		args   []any
	}{
		{
			name:   "system sees all — no clause, no args",
			viewer: access.System(),
			col:    "library_id",
			clause: "",
			args:   nil,
		},
		{
			name:   "admin sees all — no clause, no args",
			viewer: access.Admin(),
			col:    "id",
			clause: "",
			args:   nil,
		},
		{
			name:   "legacy device sees all — no clause, no args",
			viewer: access.LegacyDevice(),
			col:    "library_id",
			clause: "",
			args:   nil,
		},
		{
			name:   "user with grants — IN-list over library_id column",
			viewer: access.User(7, []int64{1, 2, 3}, nil),
			col:    "library_id",
			clause: "library_id IN (?,?,?)",
			args:   []any{int64(1), int64(2), int64(3)},
		},
		{
			name:   "user with grants — clause text uses the given column",
			viewer: access.User(7, []int64{1, 2, 3}, nil),
			col:    "id",
			clause: "id IN (?,?,?)",
			args:   []any{int64(1), int64(2), int64(3)},
		},
		{
			name:   "user with a single grant — single placeholder",
			viewer: access.User(7, []int64{42}, nil),
			col:    "library_id",
			clause: "library_id IN (?)",
			args:   []any{int64(42)},
		},
		{
			name:   "user with empty set — fail closed",
			viewer: access.User(7, nil, nil),
			col:    "library_id",
			clause: "1=0",
			args:   nil,
		},
		{
			name:   "zero viewer — fail closed",
			viewer: access.Viewer{},
			col:    "id",
			clause: "1=0",
			args:   nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			clause, args := visibleWhere(tt.viewer, tt.col)
			if clause != tt.clause {
				t.Fatalf("visibleWhere(%v, %q) clause = %q, want %q", tt.viewer, tt.col, clause, tt.clause)
			}
			if !reflect.DeepEqual(args, tt.args) {
				t.Fatalf("visibleWhere(%v, %q) args = %#v, want %#v", tt.viewer, tt.col, args, tt.args)
			}
			// Bound, not stringified: every arg element must carry the
			// int64 dynamic type (database/sql would store a string as
			// TEXT and the INTEGER comparison would silently miss).
			for i, arg := range args {
				if _, ok := arg.(int64); !ok {
					t.Fatalf("args[%d] has dynamic type %T, want int64", i, arg)
				}
			}
		})
	}
}
